using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Threading;
namespace Dafeiyu.Tests {
 public static class ConversationOwnershipUiTests {
  static int checks;static readonly BindingFlags hidden=BindingFlags.Instance|BindingFlags.NonPublic;
  static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
  static T Field<T>(object value,string name){return(T)value.GetType().GetField(name,hidden).GetValue(value);}
  static IEnumerable<T> All<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return(T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var x in All<T>(VisualTreeHelper.GetChild(root,i)))yield return x;}
  static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
  static ChatWindow Chat(){return Application.Current.Windows.OfType<ChatWindow>().Single();}
  [STAThread]public static int Main(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};PetWindow pet=null;string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ownership-ui-"+Guid.NewGuid().ToString("N"));try{
   var cfg=new PetSettings{AgentEnabled=false,ShowPredictedMessages=false,ReadReplies=false,AutoUpdate=false,GreetingEnabled=false,OnboardingState="completed",HideOnFullscreen=false};foreach(var key in cfg.Hotkeys.Keys.ToArray())cfg.Hotkeys[key]="";pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(root,"settings.json")),null);
   // All five embedded roles are fixtures here. A live E package acquisition
   // would turn synchronous fixture selection into a separate asynchronous flow.
   // Cached/startup acquisition and same-role hot reload are tested independently.
   pet.Skin.FixtureEmbedded=true;pet.Show();pet.ShowChat();Pump();var chat=Chat();chat.Width=1150;Pump();var firstSkin=pet.Skin;var secondSkin=pet.Catalog.Skins.First(s=>s.Id!=firstSkin.Id);
   var personal=Field<ConversationWorkspace>(chat,"workspace");personal.Definition.Name="FIRST_PET_PRIVATE";personal.Session.History.Commit("PRIVATE_FIRST_PET","reply");pet.PrepareConversationSubmission(personal);pet.FinishConversationSubmission(personal);chat.RefreshAppearance();Pump();Check(pet.Projects.Projects.Count==0&&pet.Projects.UnassignedConversations.Single(c=>c.Mode=="chat").PetId==firstSkin.Id,"full-window chat saves under its pet in the default section without a project folder");
   var groups=All<TextBlock>(chat).Where(t=>t.Name=="SidebarSectionTitle").Select(t=>t.Text).ToArray();Check(Array.IndexOf(groups,"默认分区")<Array.IndexOf(groups,"快速对话")&&Array.IndexOf(groups,"快速对话")<Array.IndexOf(groups,"最近"),"fixed quick group follows custom sections and precedes recent");Check(All<Button>(chat).Any(b=>b.Name=="ChatConversation_"+personal.Id),"current pet private record is visible in quick group");
   foreach(string id in new[]{"quick","recent"}){var toggle=All<Button>(chat).Single(b=>b.Name=="ToggleSection_"+id);Check(toggle.ContextMenu!=null&&toggle.ContextMenu.Items.OfType<MenuItem>().Any(m=>(string)m.Header=="重命名分区"),"fixed "+id+" group exposes rename actions");toggle.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();var sidebar=All<ProjectSidebar>(chat).Single();sidebar.Refresh();Pump();Check(All<Button>(chat).Any(b=>b.Name=="ToggleSection_"+id),"fixed "+id+" group survives collapsing");All<Button>(chat).Single(b=>b.Name=="ToggleSection_"+id).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
   Check(pet.SelectSkin(secondSkin),"switching to another pet succeeds");Pump();Check(!All<Button>(chat).Any(b=>b.Name=="ChatConversation_"+personal.Id)&&!Field<ConversationWorkspace>(chat,"workspace").Session.History.Messages.Any(m=>m.Content=="PRIVATE_FIRST_PET"),"another pet sees neither the private sidebar record nor its history");
   Check(pet.SelectSkin(firstSkin),"switching back succeeds");Pump();Check(Field<ConversationWorkspace>(chat,"workspace").Id==personal.Id&&Field<ConversationWorkspace>(chat,"workspace").Session.History.Messages.Any(m=>m.Content=="PRIVATE_FIRST_PET"),"switching back restores the first pet conversation");
   var project=ProjectCatalogStore.CreateProject(pet.Projects,"shared",root);pet.OpenProjectConversation(project,project.Conversations[0]);Pump();var work=Field<ConversationWorkspace>(chat,"workspace");work.Session.History.Commit("SHARED_WORK_HISTORY","reply");chat.ReloadHistory();pet.SelectSkin(secondSkin);Pump();Check(Field<ConversationWorkspace>(chat,"workspace").Id==work.Id&&All<RichTextBox>(chat).Any(t=>new System.Windows.Documents.TextRange(t.Document.ContentStart,t.Document.ContentEnd).Text.Contains("SHARED_WORK_HISTORY")),"work window and history stay shared while changing the visible pet");
   pet.SelectSkin(firstSkin);pet.ShowQuickChat();Pump();var quick=Field<QuickChatWindow>(pet,"quick");All<MarkdownEditor>(quick).Single(t=>t.Name=="QuickMessageInput").Text="FIRST_PET_DRAFT";pet.SelectSkin(secondSkin);Pump();quick=Field<QuickChatWindow>(pet,"quick");Check(!All<MarkdownEditor>(quick).Single(t=>t.Name=="QuickMessageInput").Text.Contains("FIRST_PET_DRAFT"),"quick drafts do not follow a different pet");pet.SelectSkin(firstSkin);Pump();quick=Field<QuickChatWindow>(pet,"quick");Check(All<MarkdownEditor>(quick).Single(t=>t.Name=="QuickMessageInput").Text=="","returning after closing quick chat starts a new empty draft");quick.Close();
   var loaded=pet.ProjectStore.Load();Check(loaded.UnassignedConversations.Any(c=>c.Id==personal.Id)&&loaded.Projects.Any(p=>p.Id==project.Id),"private and shared memberships survive catalog persistence");Console.WriteLine("Conversation ownership UI tests: "+checks+" passed");return 0;
  }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}finally{foreach(var q in app.Windows.OfType<QuickChatWindow>().ToArray())q.Close();foreach(var c in app.Windows.OfType<ChatWindow>().ToArray())c.Close();if(pet!=null)pet.Close();app.Shutdown();}}
 }
}
